use zwen_core::completion::{CompletionDecoder,FinishReason};
fn frame(text:&str,finish:Option<&str>)->String{serde_json::json!({"choices":[{"index":0,"delta":{"content":text},"finish_reason":finish}]}).to_string()}
#[test] fn content_and_finish_in_same_frame_are_preserved(){let mut d=CompletionDecoder::default();let delta=d.accept(&frame("中文",Some("length"))).unwrap();assert_eq!(delta.text,"中文");assert_eq!(delta.finish,Some(FinishReason::Length));assert!(d.accept("[DONE]").unwrap().done);assert_eq!(d.finish().unwrap(),FinishReason::Length);}
#[test] fn eof_is_never_inferred_as_success(){let mut d=CompletionDecoder::default();d.accept(&frame("partial",None)).unwrap();assert!(d.finish().is_err());let mut d=CompletionDecoder::default();d.accept(&frame("answer",Some("stop"))).unwrap();assert!(d.finish().is_err());}
#[test] fn done_requires_finish_marker(){let mut d=CompletionDecoder::default();assert!(d.accept("[DONE]").is_err());}
#[test] fn roles_and_usage_are_ignored_without_erasing_text(){let mut d=CompletionDecoder::default();assert!(d.accept(r#"{"choices":[{"index":0,"delta":{"role":"assistant"},"finish_reason":null}]}"#).unwrap().text.is_empty());d.accept(&frame("x",Some("stop"))).unwrap();assert!(d.accept(r#"{"choices":[],"usage":{"completion_tokens":1}}"#).unwrap().text.is_empty());d.accept("[DONE]").unwrap();assert_eq!(d.finish().unwrap(),FinishReason::Stop);}
#[test] fn protocol_errors_do_not_echo_provider_payload(){let mut d=CompletionDecoder::default();let err=d.accept(r#"{"error":{"message":"secret-value"}}"#).unwrap_err();assert!(!format!("{err:?}").contains("secret-value"));for s in ["broken",r#"{"choices":[{"index":0,"delta":{"tool_calls":[{}]},"finish_reason":null}]}"#,r#"{"choices":[{"index":0,"delta":{"content":[]},"finish_reason":null}]}"#]{assert!(CompletionDecoder::default().accept(s).is_err());}}
